-- テストデータ投入（山田太郎 0001・2026年6月/7月）。冪等：既存の当該データを消してから入れ直す。
-- Neon の SQL Editor に貼って実行。何度実行してもよい。
DO $$
BEGIN
  DELETE FROM "WorkDay" WHERE "employeeId"='emp_0001' AND "date" >= '2026-06-01' AND "date" < '2026-08-01';
  DELETE FROM "MonthlyClosing" WHERE "employeeId"='emp_0001' AND "year"=2026 AND "month" IN (6,7);
END $$;
